package com.wansheng.visitor.auth;
import jakarta.validation.Valid;import jakarta.validation.constraints.*;import java.security.Principal;import java.util.*;import org.springframework.http.*;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.web.bind.annotation.*;import org.springframework.web.server.ResponseStatusException;
@RestController @RequestMapping("/api/visitor/auth/users")class AccountAdminController{private static final Set<String>ROLES=Set.of("GUARD","DORM_ADMIN","ADMIN","SYSTEM_ADMIN");private final AccountRepository repo;private final PasswordEncoder encoder;AccountAdminController(AccountRepository r,PasswordEncoder e){repo=r;encoder=e;}record CreateRequest(@NotBlank @Pattern(regexp="[A-Za-z0-9._-]{3,50}")String username,@NotBlank @Size(max=100)String displayName,@NotBlank @Size(min=8,max=100)String password,@NotBlank String role){}record UpdateRequest(@NotBlank @Size(max=100)String displayName,@NotBlank String role,boolean enabled){}record PasswordRequest(@NotBlank @Size(min=8,max=100)String password){}@GetMapping List<AccountRepository.Account>list(){return repo.list();}@PostMapping @ResponseStatus(HttpStatus.CREATED)AccountRepository.Account create(@Valid @RequestBody CreateRequest r){role(r.role());repo.create(r.username(),r.displayName(),encoder.encode(r.password()),r.role());return repo.find(r.username()).orElseThrow();}@PutMapping("/{username}")AccountRepository.Account update(@PathVariable String username,@Valid @RequestBody UpdateRequest r,Principal p){role(r.role());var old=repo.find(username).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));if(username.equals(p.getName())&&!r.enabled())throw new ResponseStatusException(HttpStatus.CONFLICT,"不能停用当前账号");if(old.role().equals("SYSTEM_ADMIN")&&(!r.role().equals("SYSTEM_ADMIN")||!r.enabled())&&repo.enabledSystemAdmins()<=1)throw new ResponseStatusException(HttpStatus.CONFLICT,"必须保留一个启用的系统管理员");repo.update(username,r.displayName(),r.role(),r.enabled());return repo.find(username).orElseThrow();}@PutMapping("/{username}/password")@ResponseStatus(HttpStatus.NO_CONTENT)void password(@PathVariable String username,@Valid @RequestBody PasswordRequest r){if(repo.password(username,encoder.encode(r.password()))!=1)throw new ResponseStatusException(HttpStatus.NOT_FOUND);}@DeleteMapping("/{username}")@ResponseStatus(HttpStatus.NO_CONTENT)void delete(@PathVariable String username,Principal p){if(username.equals(p.getName()))throw new ResponseStatusException(HttpStatus.CONFLICT,"不能删除当前账号");var old=repo.find(username).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));if(old.role().equals("SYSTEM_ADMIN")&&repo.enabledSystemAdmins()<=1)throw new ResponseStatusException(HttpStatus.CONFLICT,"必须保留一个启用的系统管理员");repo.delete(username);}private static void role(String r){if(!ROLES.contains(r))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"无效角色");}}
